//! 🫙️ Actual original Flow SQLite native prefixes preserve source identity and physical retirement receipts.
use semio_framework_os_kernel as store;
use semio_framework_value::{ErasedSnapshotRetirement,ValueError,ValueRefusalKind,RetirementDemand,native_decoding::NativeDecodeRetirementRecipient,retained_clone::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep},retirement::RetireOwned};
use semio_s_artifact_stdio_semio::standards::v1::subsets::flow::schema::snapshot::{SemioFlowSnapshot,FlowNode,FlowParam,FlowEdge,PortRef};
use store::{ArtifactSqliteSnapshot,ArtifactPack,ArtifactDsl,sqlite_snapshot::{SqliteSnapshotControl,SqliteDatabaseLimits}};
#[global_allocator]
static PREFIX_HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
fn corpus()->serde_json::Value{serde_json::from_str(include_str!("../../🧫️fixtures/🫙️prefix/🔣️.json")).unwrap()}
fn policy(f:&serde_json::Value)->RetainedCloneGrant{let p=&f["policy"];RetainedCloneGrant{maximum_items:p["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:p["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:p["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:p["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:p["maximumDepth"].as_u64().unwrap()as usize}}
fn fixture(f:&serde_json::Value)->SemioFlowSnapshot{let v=&f["flow"];let node=v["nodeId"].as_str().unwrap();SemioFlowSnapshot{schema:v["schema"].as_str().unwrap().into(),nodes:vec![FlowNode{id:node.into(),kind:"original-kind".into(),label:v["label"].as_str().unwrap().repeat(f["labelRepetitions"].as_u64().unwrap()as usize),params:vec![FlowParam{key:v["parameterKey"].as_str().unwrap().into(),value:v["parameterValue"].as_str().unwrap().into()}],position:Default::default()}],edges:vec![FlowEdge{id:"original-edge".into(),from:PortRef{node:node.into(),port:v["sourcePort"].as_str().unwrap().into()},to:PortRef{node:node.into(),port:v["targetPort"].as_str().unwrap().into()},kind:"original-edge-kind".into()}]}}
fn demand(owner:&dyn ErasedSnapshotRetirement)->RetirementDemand{let copy=owner.next_copy_byte_demand().unwrap();let release=owner.next_release_byte_demand().unwrap();owner.next_demand(if copy==0{release}else{copy}).unwrap()}
fn close(owner:&mut dyn ErasedSnapshotRetirement,grant:RetainedCloneGrant)->(usize,usize){
let mut born=0;let mut freed=0;for _ in 0..1000000{
if owner.terminal_is_empty(){return(born,freed)}let d=demand(owner);assert!(d.copy_bytes<=grant.maximum_copy_bytes&&d.capacity_bytes<=grant.maximum_capacity_bytes&&d.release_bytes<=grant.maximum_release_bytes&&d.depth<=grant.maximum_depth);
for axis in 0..5{let mut denied=grant;let active=match axis{0=>{denied.maximum_items=0;1},1=>{denied.maximum_copy_bytes=d.copy_bytes.saturating_sub(1);d.copy_bytes},2=>{denied.maximum_capacity_bytes=d.capacity_bytes.saturating_sub(1);d.capacity_bytes},3=>{denied.maximum_release_bytes=d.release_bytes.saturating_sub(1);d.release_bytes},_=>{denied.maximum_depth=d.depth.saturating_sub(1);d.depth}};if active==0{continue}
let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.close_step(denied));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0),"denied currency changed original prefix backing");if axis==4{assert_eq!(result.unwrap_err().kind,ValueRefusalKind::DepthLimit)}else{assert_eq!(result.unwrap().progress(),RetainedCloneProgress::default())}assert_eq!(demand(owner),d);assert!(!owner.terminal_is_empty());
}
let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.close_step(grant).unwrap());let progress=step.progress();assert!(progress.fits(grant));assert_eq!(heap.requested_bytes,progress.retained_capacity_bytes);assert_eq!(heap.released_bytes,progress.released_bytes);born+=heap.requested_bytes;freed+=heap.released_bytes;
if matches!(step,RetainedCloneStep::Complete(_)){assert!(owner.terminal_is_empty());return(born,freed)}
}panic!("original prefix close did not converge")
}
fn close_value<T:RetireOwned>(original:T,grant:RetainedCloneGrant)->(usize,usize){let mut original=Some(original);let mut owner=None;let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||store::artifact_retirement_admit_owned(&mut original,&mut owner,grant).unwrap());assert!(original.is_none());assert_eq!(heap.requested_bytes,step.progress().retained_capacity_bytes);assert_eq!(heap.released_bytes,step.progress().released_bytes);let(mut born,mut freed)=close(owner.as_mut().unwrap().as_mut(),grant);born+=heap.requested_bytes;freed+=heap.released_bytes;let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||store::artifact_retirement_box_close_step(&mut owner,grant).unwrap());assert!(owner.is_none());assert_eq!(heap.requested_bytes,step.progress().retained_capacity_bytes);assert_eq!(heap.released_bytes,step.progress().released_bytes);(born+heap.requested_bytes,freed+heap.released_bytes)}
/// 🗃️ Creates a test input through its original recipient and authored caller close policy.
fn fixture_database<T:ArtifactSqliteSnapshot>(snapshot:&T)->store::sqlite_snapshot::SqliteDatabase{
let grant=policy(&corpus());let mut recipient=NativeDecodeRetirementRecipient::new();let database={let mut control=SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default());control.install_native_retirement_recipient(&mut recipient).unwrap();snapshot.to_sqlite_database(&mut control).unwrap()};close(&mut recipient,grant);database
}
fn source(payload:&store::io::IoPayload)->(*const u8,usize){match payload{store::io::IoPayload::Binary(v)=>(v.as_ptr(),v.len()),store::io::IoPayload::Text(v)=>(v.as_ptr(),v.len())}}
#[test]
fn native_prefix_original_flow_success_and_cancelled_interior(){
let f=corpus();let grant=policy(&f);let expected=fixture(&f);let mut prefixes=0;
for encoding in f["encodings"].as_array().unwrap(){let payload=if encoding=="binary"{store::io::IoPayload::Binary(expected.encode_pack())}else{store::io::IoPayload::Text(expected.print_dsl())};let original=source(&payload);
for(stop,mode)in f["stops"].as_array().unwrap().iter().map(|v|(v.as_u64().unwrap()as usize,"count")).chain(f["interiorPhases"].as_array().unwrap().iter().map(|v|(usize::MAX,v.as_str().unwrap()))).chain(std::iter::once((usize::MAX,"success"))){
let mut recipient=NativeDecodeRetirementRecipient::new();let mut count=0;let mut label_stage=0;let mut interior=false;
let label_bytes=expected.nodes[0].label.len();let key_bytes=expected.nodes[0].params[0].key.len();
let mut callback=|event:store::sqlite_snapshot::SqliteSnapshotProgress|{let current=count;count+=1;if event.total==label_bytes&&event.completed==0{label_stage+=1}let cancel=(mode=="label"&&label_stage>=3&&event.total==label_bytes&&event.completed>=65536)||(mode=="parameter"&&label_stage>=3&&event.total==key_bytes&&event.completed==key_bytes);interior|=cancel;current!=stop&&!cancel};
let((result,admitted),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let mut control=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default());control.install_native_retirement_recipient(&mut recipient).unwrap();let result=SemioFlowSnapshot::decode_sqlite_snapshot_native(&payload,&mut control);(result,SqliteDatabaseLimits::default().max_allocation_bytes-control.allocation_remaining_bytes())});
assert_eq!(source(&payload),original);assert_eq!(heap.released_bytes,0,"normal decode released an original prefix");let mut born=heap.requested_bytes;let mut freed=0;
match result{Ok(actual)=>{assert_eq!(actual,expected);assert_eq!(mode,"success");assert_eq!(admitted,heap.requested_bytes);let(b,r)=close_value(actual,grant);born+=b;freed+=r},Err(error)=>{assert_eq!(error.kind,ValueRefusalKind::Canceled);if mode!="count"{assert!(interior);assert!(heap.requested_bytes>=label_bytes,"interior cancellation lacks the real long label backing")}if recipient.has_owner(){prefixes+=1;assert!(admitted>0)}let(b,r)=close_value(error,grant);born+=b;freed+=r}}
let(b,r)=close(&mut recipient,grant);born+=b;freed+=r;assert_eq!(born,freed,"whole original prefix and refusal metadata physical balance");let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(recipient));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
}
}assert!(prefixes>=2);println!("[DEBUG] Actual original Flow binary/text native prefixes retained source pointers, all5 denied currencies and exact caller-funded physical close; cancelledPrefixes={prefixes}");
}
