fn native_prefix_missing_recipient_refuses_before_owned_materialization(){let f=corpus();let expected=fixture(&f);let payload=store::io::IoPayload::Binary(expected.encode_pack());let pointer=source(&payload);let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||SemioFlowSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())));assert_eq!(result.unwrap_err().kind,ValueRefusalKind::OwnershipLimit);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(source(&payload),pointer);println!("[DEBUG] Missing caller recipient rejected original Flow source before any materialized prefix");}

